export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/crcgen; rm -rf $D; mkdir -p $D; cd $D || exit 1
base64 -d > p.zip <<'B64EOF'

B64EOF
unzip -oq p.zip -d $D
make_tcl() { :; }
runone() { t=$1; /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; tail -n 3 $t.log; fi; }
export -f runone
for t in base c00 c01 c02 c03 c04 c05 c06 c07 c08 c09 c10 c11 c12 c13 c14 c15 c16 c17 c18 c19 c20 c21 c22 c23 c24 c25 c26 c27 c28 c29 c30 c31 c32 c33 c34 c35 c36 c37 c38 c39 c40 c41 c42 c43 c44 c45 c46 c47 c48 c49 c50 c51 c52 c53 c54 c55 c56 c57 c58 c59 c60 c61 c62 c63; do :; done
ls *.tcl | sed 's/.tcl$//' > tags.txt
cat tags.txt | xargs -P 24 -I{} bash -c 'runone {}'
tar czf /tmp/crcgen_out.tgz *.bit
echo CRCGENDONE
